using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ForestryChecks {
 static void Require(bool condition,string why){if(!condition)throw new Exception(why);}
 [MenuItem("BWVR/Verify renewable forestry model")]
 public static void VerifyModel(){var s=new ResourceState();var tree=s.Ensure("tree",VillageResource.Wood);Require(!s.Plant(tree.id),"Living tree replanted");tree.felled=true;for(int i=0;i<4;i++){Require(s.Harvest(0,tree.id,3)==3,"Finite tree harvest failed");if(i==3)Require(!s.Plant(tree.id),"Pending timber was erased by replanting");s.Deposit(0);}Require(s.wood==12&&s.Plant(tree.id)&&!s.Plant(tree.id)&&tree.remaining==0,"Planting duplicated supplies or claims");Require(s.Harvest(1,tree.id,3)==0,"Growing tree yielded wood");Require(!s.Grow(tree.id,float.NaN)&&!s.Grow(tree.id,-1)&&!s.Grow(tree.id,150)&&Mathf.Abs(tree.growth-.5f)<.001f,"Growth timer invalid");var restored=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(s));Require(restored.Valid()&&restored.Find(tree.id).growth==tree.growth,"Growth save failed");Require(restored.Grow(tree.id,150)&&restored.Find(tree.id).remaining==12&&!restored.Find(tree.id).felled&&restored.Find(tree.id).regrown==1,"Regrowth not exactly one finite tree");Require(!restored.Grow(tree.id,500)&&restored.Find(tree.id).regrown==1,"Mature tree generated repeat yield");Require(restored.Harvest(1,tree.id,3)==3&&restored.Valid(),"Renewed tree not harvestable");var invalid=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(s));invalid.cargo[1].source=tree.id;invalid.cargo[1].amount=1;invalid.cargo[1].kind=VillageResource.Wood;Require(!invalid.Valid(),"Cargo coexists with regrowing tree");invalid=JsonUtility.FromJson<ResourceState>(JsonUtility.ToJson(s));invalid.Find(tree.id).growth=2;Require(!invalid.Valid(),"Invalid growth accepted");Require(new SliceState().Valid(),"Legacy season invalid");Debug.Log("BWVR_FORESTRY_MODEL_PASS: finite harvest, pending cargo protection, exclusive planting, saved growth, exactly-once renewal, corruption/legacy validation");}
 [MenuItem("BWVR/Verify native replanting (Play mode)")]
 public static void VerifyRuntime(){Require(EditorApplication.isPlaying,"Enter Play mode");var world=UnityEngine.Object.FindAnyObjectByType<VillageResources>();var slice=world.GetComponentInParent<QuestSlice>();var f=typeof(QuestSlice).GetField("state",BindingFlags.Instance|BindingFlags.NonPublic);var original=(SliceState)f.GetValue(slice);var god=slice.GetComponentInChildren<CreatureHybrid>();var positions=world.Gatherers.Select(a=>a.transform.position).ToArray();god.Interrupt("Forestry QA");foreach(var a in world.Gatherers){a.Cancel();a.GetComponent<VillagerSocial>().ResetTask();a.GetComponent<VillagerExploration>().ResetTask();a.GetComponent<VillagerBlockPlay>().ResetTask();}var test=new SliceState{developmentFocus=true};f.SetValue(slice,test);world.ResetWorld();try{var node=world.sources.First(s=>s.tree!=null&&world.Safe(s));var record=test.Resources.Find(node.id);record.remaining=0;record.felled=true;world.Refresh();var actor=world.Gatherers[1];actor.transform.position=node.approach;actor.GetComponent<IslandNavigator>().ResetRoute();Require(actor.TryReplant(node)&&!world.Gatherers[2].TryReplant(node),"Planting reservation not exclusive");Require(node.tree.ResourceReserved&&!node.tree.Available,"Creature can take planting site");actor.Tick(30,true);world.Advance(30,true);Require(!record.growing&&record.plantings==0,"Paused planting advanced");actor.GetComponent<CarryItem>().held=true;actor.Tick(.1f,false);actor.GetComponent<CarryItem>().held=false;Require(!actor.Active&&node.owner==null&&!record.growing&&!node.tree.ResourceReserved,"Interrupted planting stranded ownership or granted growth");Require(actor.TryReplant(node),"Cannot retry planting");for(int n=0;n<4000&&actor.Active;n++)actor.Tick(.05f,false);Require(!actor.Active&&record.growing&&record.plantings==1&&record.remaining==0&&node.owner==null,"Native villager failed to plant");Require(node.sapling.gameObject.activeSelf&&node.tree.Harvested&&!node.visual.gameObject.activeSelf,"Sapling/stump visuals disagree");float initial=node.sapling.localScale.y;world.Advance(150,false);Require(record.growth>.49f&&node.sapling.localScale.y>initial&&record.remaining==0,"Sapling not visibly growing");float growth=record.growth;world.Advance(30,true);Require(record.growth==growth,"Paused sapling grew");var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid(),"Planted save invalid");f.SetValue(slice,saved);world.ResetWorld();record=saved.Resources.Find(node.id);Require(record.growing&&record.growth==growth&&node.sapling.gameObject.activeSelf,"Reload lost tree growth");int obstacles=world.Navigation.obstacleCount;world.Advance(151,false);Require(!record.growing&&record.regrown==1&&record.remaining==12&&!node.tree.Harvested&&!node.sapling.gameObject.activeSelf&&world.Navigation.obstacleCount==obstacles,"Mature tree did not restore original art/rooted footprint");Require(actor.TryBegin(node),"Regrown tree cannot be harvested");actor.Cancel();Require(saved.Valid(),"Final forestry state invalid");Debug.Log("BWVR_FORESTRY_RUNTIME_PASS: native planting, exclusive reservations, carried-worker cancellation, pause, growing CC0 art, saved stages, finite renewal, rooted navigation and harvestability");}finally{foreach(var a in world.Gatherers)a.Cancel();f.SetValue(slice,original);world.ResetWorld();for(int i=0;i<positions.Length;i++){world.Gatherers[i].transform.position=positions[i];world.Gatherers[i].GetComponent<IslandNavigator>().ResetRoute();}}}
}
}
